const fs=require('fs'),path=require('path'),cp=require('child_process'),crypto=require('crypto');
const root=process.cwd(),work=path.join(root,'launcher-build');fs.mkdirSync(work,{recursive:true});
const run=(cmd,args,cwd=work)=>cp.execFileSync(cmd,args,{cwd,stdio:'inherit',shell:cmd==='npm'});
run('gh',['release','download','v0.4.9','-R',process.env.GITHUB_REPOSITORY,'-p','BluStudio-Launcher.exe','-D',work]);
const unpack=path.join(work,'runtime');run('7z',['x',path.join(work,'BluStudio-Launcher.exe'),'-o'+unpack,'-y']);
function walk(dir){return fs.readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(dir,e.name)):[path.join(dir,e.name)]);}
let files=walk(unpack),asarFile=files.find(p=>p.endsWith(path.join('resources','app.asar')));
if(!asarFile){for(const archive of files.filter(p=>p.endsWith('.7z'))){run('7z',['x',archive,'-o'+unpack,'-y']);}asarFile=walk(unpack).find(p=>p.endsWith(path.join('resources','app.asar')));}
if(!asarFile)throw Error('Missing runtime app.asar');
fs.rmSync(path.join(unpack,'$PLUGINSDIR'),{recursive:true,force:true});
const runtime=path.dirname(path.dirname(asarFile)),src=JSON.parse(fs.readFileSync(path.join(root,'.github/launcher-src/source.json'),'utf8'));
fs.writeFileSync(path.join(work,'package.json'),src['package.json']);
run('npm',['install','--ignore-scripts','--no-audit','--no-fund']);
const asar=require(path.join(work,'node_modules','@electron','asar')),app=path.join(work,'extracted-app');asar.extractAll(asarFile,app);
for(const [name,data] of Object.entries(src)){fs.writeFileSync(path.join(app,name),data);if(name==='build-portable.cjs')fs.writeFileSync(path.join(work,name),data);}
const branding=JSON.parse(fs.readFileSync(path.join(root,'.github/launcher-src/branding.json'),'utf8'));for(const name of ['studio.png','studio.ico'])fs.writeFileSync(path.join(app,'assets',name),Buffer.from(branding[name],'base64'));
fs.cpSync(path.join(app,'assets'),path.join(work,'assets'),{recursive:true});
const native=path.join(app,'assets','blu-updater.exe'),cs=path.join(root,'.github','launcher-src','native-updater.cs');const quote=s=>s.replace(/'/g,"''");run('powershell.exe',['-NoProfile','-NonInteractive','-Command',"Add-Type -Path '"+quote(cs)+"' -ReferencedAssemblies System.dll,System.Core.dll,System.Web.Extensions.dll,System.Windows.Forms.dll -OutputAssembly '"+quote(native)+"' -OutputType WindowsApplication"]);if(fs.statSync(native).size<1000)throw Error('Missing native updater helper');

const renamedExe=path.join(runtime,'Bluu-Client.exe');fs.renameSync(path.join(runtime,'BluStudio-Launcher.exe'),renamedExe);const rcedit=path.join(work,'node_modules','electron-winstaller','vendor','rcedit.exe');run(rcedit,[renamedExe,'--set-icon',path.join(work,'assets','studio.ico'),'--set-version-string','ProductName','Bluu Client','--set-version-string','FileDescription','Bluu Client','--set-version-string','OriginalFilename','Bluu-Client.exe','--set-file-version','0.4.26','--set-product-version','0.4.26']);
for(const p of walk(runtime)){if(path.basename(p).startsWith('.BluStudio-Launcher.exe')||(path.dirname(p).endsWith('locales')&&!['es.pak','es-419.pak','en-US.pak'].includes(path.basename(p))))fs.unlinkSync(p);}
(async()=>{fs.unlinkSync(asarFile);run(process.execPath,['-e',"require('@electron/asar').createPackage(process.argv[1],process.argv[2]).catch(e=>{console.error(e);process.exitCode=1})",app,asarFile]);if(fs.statSync(asarFile).size<1000000)throw Error('Empty or incomplete application archive');asar.uncacheAll();if(JSON.parse(asar.extractFile(asarFile,'package.json')).version!=='0.4.26')throw Error('Wrong archived application version');const out=path.join(work,'release');run(process.execPath,[path.join(work,'build-portable.cjs'),'--prepackaged',runtime,'--output',out]);const exe=path.join(out,'Bluu-Client.exe');const verifyBrand="$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing;foreach($file in @('"+quote(exe)+"','"+quote(renamedExe)+"')){$v=[Diagnostics.FileVersionInfo]::GetVersionInfo($file);if($v.ProductName -ne 'Bluu Client' -or !$v.ProductVersion.StartsWith('0.4.26')){throw 'Wrong executable branding'};$icon=[Drawing.Icon]::ExtractAssociatedIcon($file);$b=$icon.ToBitmap();$white=0;$red=0;for($x=0;$x -lt $b.Width;$x++){for($y=0;$y -lt $b.Height;$y++){$c=$b.GetPixel($x,$y);if($c.A -gt 64){if($c.R -gt 220 -and $c.G -gt 220 -and $c.B -gt 220){$white++};if($c.R -gt 150 -and $c.G -lt 120 -and $c.B -lt 120){$red++}}}};$b.Dispose();$icon.Dispose();if($white -lt 10 -or $red -gt 0){throw 'Old or empty Windows icon'}};Write-Output 'PASS Windows branding: Bluu Client name, version and white transparent icon'";run('powershell.exe',['-NoProfile','-NonInteractive','-Command',verifyBrand]);const data=fs.readFileSync(exe);if(data.toString('ascii',0,2)!=='MZ')throw Error('Invalid executable');const audit=path.join(work,'artifact-audit');run('7z',['x',exe,'-o'+audit,'-y']);let audited=walk(audit).find(p=>p.endsWith(path.join('resources','app.asar')));if(!audited){for(const a of walk(audit).filter(p=>p.endsWith('.7z')))run('7z',['x',a,'-o'+audit,'-y']);audited=walk(audit).find(p=>p.endsWith(path.join('resources','app.asar')));}if(!audited||fs.statSync(audited).size<1000000)throw Error('Final EXE has missing or empty app.asar');if(crypto.createHash('sha256').update(fs.readFileSync(audited)).digest('hex')!==crypto.createHash('sha256').update(fs.readFileSync(asarFile)).digest('hex'))throw Error('Final EXE payload differs from tested application');asar.uncacheAll();if(JSON.parse(asar.extractFile(audited,'package.json')).version!=='0.4.26')throw Error('Final EXE version mismatch');if(asar.extractFile(audited,'assets/blu-updater.exe').length<1000)throw Error('Final EXE missing native updater');console.log('PASS final EXE audit: nonempty app.asar, exact payload digest, version 0.4.26');const meta={kind:'blu-studio-app',version:'0.4.26',url:'https://github.com/'+process.env.GITHUB_REPOSITORY+'/releases/download/v0.4.26/Bluu-Client.exe',sha256:crypto.createHash('sha256').update(data).digest('hex')};fs.writeFileSync(path.join(root,'.github/launcher-src/build.json'),JSON.stringify(meta,null,2)+'\n');run('gh',['release','create','v0.4.26',exe,'--draft','--title','Bluu Client','--notes','Restaura sesiones de jugadores invitados; selector de cuentas verificadas con caras de skins y UUID; recarga del catálogo e identidad visible en el menú.','-R',process.env.GITHUB_REPOSITORY]);run('git',['config','user.name','github-actions[bot]'],root);run('git',['config','user.email','41898282+github-actions[bot]@users.noreply.github.com'],root);run('git',['add','.github/launcher-src/build.json'],root);run('git',['commit','-m','Record signed-release build digest for 0.4.26'],root);run('git',['pull','--rebase'],root);run('git',['push'],root);})().catch(e=>{console.error(e);process.exit(1)});
